import javax.swing.*; import javax.swing.table.DefaultTableModel; import javax.swing.table.TableRowSorter; import java.awt.*; import java.util.regex.Pattern;
public class W18E04_CompleteSystem {
 private final DefaultTableModel m=new DefaultTableModel(new String[]{"ID","Name","Category"},0);private final JTable t=new JTable(m);private final JTextField id=new JTextField(5),nameF=new JTextField(10),cat=new JTextField(8),search=new JTextField(12);
 public W18E04_CompleteSystem(){JFrame f=new JFrame("Library System");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setSize(820,450);TableRowSorter<DefaultTableModel> sorter=new TableRowSorter<>(m);t.setRowSorter(sorter);JButton add=new JButton("Add"),update=new JButton("Update"),del=new JButton("Delete"),find=new JButton("Search");
 add.addActionListener(e->m.addRow(new Object[]{id.getText(),nameF.getText(),cat.getText()}));update.addActionListener(e->{int r=t.getSelectedRow();if(r>=0){r=t.convertRowIndexToModel(r);m.setValueAt(id.getText(),r,0);m.setValueAt(nameF.getText(),r,1);m.setValueAt(cat.getText(),r,2);}});del.addActionListener(e->{int r=t.getSelectedRow();if(r>=0)m.removeRow(t.convertRowIndexToModel(r));});find.addActionListener(e->{String q=search.getText();sorter.setRowFilter(q.isBlank()?null:RowFilter.regexFilter("(?i)"+Pattern.quote(q)));});t.getSelectionModel().addListSelectionListener(e->{int r=t.getSelectedRow();if(r>=0){r=t.convertRowIndexToModel(r);id.setText(m.getValueAt(r,0).toString());nameF.setText(m.getValueAt(r,1).toString());cat.setText(m.getValueAt(r,2).toString());}});
 JPanel top=new JPanel();top.add(new JLabel("ID"));top.add(id);top.add(new JLabel("Name"));top.add(nameF);top.add(new JLabel("Category"));top.add(cat);top.add(add);top.add(update);top.add(del);JPanel bottom=new JPanel();bottom.add(new JLabel("Search"));bottom.add(search);bottom.add(find);f.add(top,BorderLayout.NORTH);f.add(new JScrollPane(t),BorderLayout.CENTER);f.add(bottom,BorderLayout.SOUTH);f.setLocationRelativeTo(null);f.setVisible(true);}
 public static void main(String[] args){SwingUtilities.invokeLater(W18E04_CompleteSystem::new);}
}
